    FR_FR,
    ES,
    ES_ES,
    IT,
    IT_IT,
    EN,
    EN_CA,
    EN_GB,
    EN_IE,
    EN_US,
    DE,
    DE_DE,
    DE_AT,
    DE_CH,
    PL,
    PL_PL;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeCuratedRecommendationLocale: FfiConverterRustBuffer<CuratedRecommendationLocale> {
    override fun read(buf: ByteBuffer) = try {
        CuratedRecommendationLocale.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: CuratedRecommendationLocale) = 4UL

    override fun write(value: CuratedRecommendationLocale, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







/**
 * Public error type exposed to consumers via UniFFI.
 *
 * This is a simplified version of [`Error`] suitable for cross-platform callers,
 * distinguishing network failures from other errors.
 */
sealed class CuratedRecommendationsApiException: kotlin.Exception() {
    
    /**
     * A network-level failure (e.g. DNS resolution, connection timeout).
     */
    class Network(
        
        val `reason`: kotlin.String
        ) : CuratedRecommendationsApiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * Any other error, including HTTP errors and deserialization failures.
     */
    class Other(
        
        val `code`: kotlin.UShort?, 
        
        val `reason`: kotlin.String
        ) : CuratedRecommendationsApiException() {
        override val message
            get() = "code=${ `code` }, reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CuratedRecommendationsApiException> {
        override fun lift(error_buf: RustBuffer.ByValue): CuratedRecommendationsApiException = FfiConverterTypeCuratedRecommendationsApiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCuratedRecommendationsApiError : FfiConverterRustBuffer<CuratedRecommendationsApiException> {
    override fun read(buf: ByteBuffer): CuratedRecommendationsApiException {
        

        return when(buf.getInt()) {
            1 -> CuratedRecommendationsApiException.Network(
                FfiConverterString.read(buf),
                )
            2 -> CuratedRecommendationsApiException.Other(
                FfiConverterOptionalUShort.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CuratedRecommendationsApiException): ULong {
        return when(value) {
            is CuratedRecommendationsApiException.Network -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is CuratedRecommendationsApiException.Other -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterOptionalUShort.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: CuratedRecommendationsApiException, buf: ByteBuffer) {
        when(value) {
            is CuratedRecommendationsApiException.Network -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is CuratedRecommendationsApiException.Other -> {
                buf.putInt(2)
                FfiConverterOptionalUShort.write(value.`code`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





